package main

import "fmt"

type Point struct{ X, Y int }

// String() string makes Point satisfy fmt.Stringer implicitly.
func (p Point) String() string {
	return fmt.Sprintf("(%d, %d)", p.X, p.Y)
}

func main() {
	p := Point{1, 2}
	fmt.Println(p) // fmt calls String() -> (1, 2)
}

