package solution

import (
	"math"
	"testing"
)

func TestSolve(t *testing.T) {
	cases := []struct {
		name   string
		in     []Shape
		want   float64
	}{
		{"empty", nil, 0},
		{"one rect", []Shape{Rectangle{2, 3}}, 6},
		{"mixed", []Shape{Rectangle{2, 3}, Circle{1}}, 6 + math.Pi},
	}
	for _, c := range cases {
		if got := Solve(c.in); math.Abs(got-c.want) > 1e-9 {
			t.Errorf("%s: Solve()=%v want %v", c.name, got, c.want)
		}
	}
}

