type DBError struct{ msg string }
func (e *DBError) Error() string { return e.msg }

func query() error {
	// Return the interface's untyped nil on success, or a real *DBError on failure.
	if false { // pretend: only on a real failure
		return &DBError{"db down"}
	}
	return nil // true nil interface: both type and value are nil
}

func main() {
	if err := query(); err != nil {
		fmt.Println("error:", err)
	} else {
		fmt.Println("no error")
	}
}

func Describe(vals []any) []string {
	out := make([]string, 0, len(vals)) // pre-size to avoid regrowth
	for _, v := range vals {
		switch x := v.(type) { // type switch recovers the concrete type
		case int:
			out = append(out, fmt.Sprintf("int:%d", x))
		case string:
			out = append(out, fmt.Sprintf("str:%s", x))
		default:
			out = append(out, "other")
		}
	}
	return out
}
